        # Simple straight-line distance heuristic
        return abs(a[0] - b[0)] + abs(a[1] - b[1))

    def a_star_search(graph, start, goal):
        frontier = [{'state': start, 'cost': 0, 'path': [start]}]
        explored = set()
        while frontier:
            current_node = min(frontier, key=lambda x: x['cost'])
            frontier.remove(current_node)
            explored.add(current_node['state'])

            if current_node['state'] == goal:
                return current_node['path']

            for neighbor in graph.get(current_node['state'], []):
                new_cost = current_node['cost'] + 1  # Assuming all edges have equal weight
                new_path = current_node['path'] + [neighbor]
                if neighbor not in explored:
                    frontier.append({'state': neighbor, 'cost': new_cost, 'path': new_path})
                    frontier.sort(key=lambda x: x['cost'] + heuristic(x['state'], goal))

        return None

    return a_star_search(graph, start, goal)

