def find_path(graph, start, goal):

    def dfs(graph, current, visited, path):
        if current == goal:
            return path + [current]
        visited.add(current)
        path.append(current)
        for neighbor in graph.get(current, []):
            if neighbor not in visited:
                result = dfs(graph, neighbor, visited, path)
                if result is not None:
                    return result
        return None
    visited = set()
    return dfs(graph, start, visited, [])
