        if vertex == goal:
            return True
        seen.add(vertex)
        for next_vertex in graph.get(vertex, []):
            if next_vertex not in seen:
                path.add(next_vertex)
                if search(graph, next_vertex, path, seen):
                    return True
                path.remove(next_vertex)
        return False
    path = {start}
    seen = set()
    if start not in seen:
        seen.add(start)
        if search(graph, start, path, seen):
            return list(path)
    return None

def find_path(graph, start, goal):
    stack = [(start, [start])]
    while stack:
        node, path = stack.pop()
        if node == goal:
            return path
        for neighbor in graph[node]:
            if neighbor not in path:
                stack.append((neighbor, path + [neighbor]))
    return None
